<?php
require __DIR__.'/expense_copies_resume_442.php';
function expenseCopyTrigger(string$table,string$condition,string$sql,string$timing='AFTER'):void{global$db,$p;$db->query($db->driver()==='mysql'?"CREATE TRIGGER {$p}expense_copy_late {$timing} INSERT ON {$p}{$table} FOR EACH ROW BEGIN IF {$condition} THEN {$sql}; END IF; END":"CREATE TRIGGER {$p}expense_copy_late {$timing} INSERT ON {$p}{$table} WHEN {$condition} BEGIN {$sql}; END");}
$review=expenseCopyReview($b,$ib);$errors=['issuer_expense_copy_unconfirmed','company_expense_copy_stale','company_expense_copy_denied','issuer_expense_write_unconfirmed','company_expense_reference_denied','company_expense_denied','issuer_storage_failed'];
$attacks=[
 ['issuers_audit',"NEW.event='company_expense_copied'","UPDATE {$p}company_expenses SET note='late source changed' WHERE id={$ib}"],
 ['issuers_audit',"NEW.event='company_expense_copied'","UPDATE {$p}company_expenses SET amount_cents=amount_cents+1 WHERE id=NEW.subject_id"],
 ['issuers_audit',"NEW.event='company_expense_copied'","UPDATE {$p}company_expense_categories SET name='late target changed' WHERE id={$targetB}"],
 ['issuers_audit',"NEW.event='company_expense_copied'","UPDATE {$p}company_projects SET status='cancelled' WHERE id=12"],
 ['issuers_audit',"NEW.event='company_expense_copied'","UPDATE {$p}staff SET active=0 WHERE staffid=7"],
 ['issuers_audit',"NEW.event='company_expense_copied'","UPDATE {$p}company_expense_requests SET input_hash='".str_repeat('f',64)."' WHERE result_id=NEW.subject_id AND operation='create'"],
 ['company_expense_copies','1=1',"UPDATE {$p}company_expenses SET note='late result changed' WHERE id=NEW.result_expense_id"],
 ['company_expense_copies','1=1',"UPDATE {$p}company_expenses SET issuer_id={$a} WHERE id=NEW.source_expense_id"]
];
foreach($attacks as$n=>[$table,$condition,$sql]){$before=expenseCopyState();expenseCopyTrigger($table,$condition,$sql);try{expenseCopyReject(fn()=>$copies->create($b,7,$ib,$review,$copyKey('atomic-'.$n)),$errors,'late source/result/reference/actor/receipt veto '.$n);}finally{$db->query('DROP TRIGGER '.$p.'expense_copy_late');}essentialCheck(expenseCopyState()===$before,'whole transaction rollback preserves native costs/journal/requests/audit/source '.$n);$r=$copies->create($b,7,$ib,$review,$copyKey('atomic-'.$n));essentialCheck($copies->create($b,7,$ib,$review,$copyKey('atomic-'.$n))===$r,'same key after rollback creates precisely one new cost '.$n);}
foreach(['company_expenses','company_financial_events','company_expense_requests','company_expense_copies']as$t){$before=expenseCopyState();$db->failOn='INSERT INTO '.$p.$t;try{essentialThrows(fn()=>$copies->create($b,7,$ib,$review,$copyKey('storage-'.$t)),'issuer_storage_failed','storage failure '.$t.' rejects copy');}finally{$db->failOn=null;}essentialCheck(expenseCopyState()===$before,'write failure restores all original rows '.$t);}
$finalKey=$copyKey('final-audit');$before=expenseCopyState();$sql=$db->driver()==='mysql'?"SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic late copy audit'":"SELECT RAISE(ABORT,'synthetic late copy audit')";expenseCopyTrigger('issuers_audit',"NEW.event='company_expense_copied'",$sql,'BEFORE');try{essentialThrows(fn()=>$copies->create($b,7,$ib,$review,$finalKey),'issuer_storage_failed','copy final audit denial rolls back native expense and receipt');}finally{$db->query('DROP TRIGGER '.$p.'expense_copy_late');}essentialCheck(expenseCopyState()===$before,'late audit failure preserves every cost and source');$r=$copies->create($b,7,$ib,$review,$finalKey);
$readAttacks=["UPDATE {$p}company_expenses SET amount_cents=amount_cents+1 WHERE id=NEW.subject_id","UPDATE {$p}staff SET active=0 WHERE staffid=7","UPDATE {$p}company_expense_requests SET input_hash='".str_repeat('e',64)."' WHERE result_id=NEW.subject_id AND operation='create'","DELETE FROM {$p}company_expense_copies WHERE result_expense_id=NEW.subject_id"];
foreach($readAttacks as$n=>$sql){$before=expenseCopyState();expenseCopyTrigger('issuers_audit',"NEW.event='company_expense_copy_viewed'",$sql);try{expenseCopyReject(fn()=>$copies->receipt($b,7,$finalKey),$errors,'receipt reader revalidates after final audit '.$n);}finally{$db->query('DROP TRIGGER '.$p.'expense_copy_late');}essentialCheck(expenseCopyState()===$before,'receipt late failure returns no DTO and rolls back audit/mutations '.$n);}
echo 'Expense copy442 atomic native source/receipt/readbacks: '.$GLOBALS['essentialChecks'].' checks ('.$db->driver().').'.PHP_EOL;
